mapper.select:
SELECT bill_no, COUNT(*) n FROM sn_order_alert WHERE status = 'OPEN' AND bill_no IN
#{b}
GROUP BY bill_no

mapper.update:
UPDATE sn_order_alert SET status = 'CLOSED', closed_by = #{by}, closed_at = #{now}, close_action = #{action},
  note = #{note}, updated_at = #{now}
WHERE id = #{id}

mapper.sql:
FROM sn_order_alert a LEFT JOIN sn_bill_ledger l ON l.bill_no = a.bill_no
WHERE 1=1
AND a.status = #{status}
AND a.bill_no = #{billNo}
AND a.alert_type = #{type}
